import{_ as o,c as s,o as n,j as a,Y as r,t as i}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"git-for-each-ref | x-cmd man (git man1) | Output information on each ref","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-for-each-ref - Output information on each ref","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-for-each-ref | x-cmd man (git man1) | Output information on each ref"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-for-each-ref - Output information on each ref"}]]},"headers":[],"params":{"isMan":true,"man":"git-for-each-ref","category":"git man1","desc":"Output information on each ref"},"relativePath":"git/man1/git-for-each-ref.md","filePath":"git/man1/[man].md"}'),h={name:"git/man1/git-for-each-ref.md"},g={class:"visually-hidden"};function l(e,t,p,c,d,u){return n(),s("div",null,[a("h1",g,i(e.$params.man),1),t[0]||(t[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-for-each-ref - Output information on each ref</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for-each-ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--count=&lt;count&gt;] [--shell</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--perl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--python</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--tcl]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   [(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)...] [--format</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pattern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   [--points-at</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   [--merged[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] [--no-merged[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   [--contains[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] [--no-contains[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Iterate over all refs that match <strong>&lt;pattern&gt;</strong> and show them according to the given <strong>&lt;format&gt;</strong>, after sorting them according to the given set of <strong>&lt;key&gt;</strong>. If <strong>&lt;count&gt;</strong> is given, stop after showing that many refs. The interpolated values in <strong>&lt;format&gt;</strong> can optionally be quoted as string literals in the specified host language allowing their direct evaluation in that language.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>&lt;pattern&gt;...</p><blockquote><p>If one or more patterns are given, only refs are shown that match against at least one pattern, either using fnmatch(3) or literally, in the latter case matching completely or from the beginning up to a slash.</p></blockquote><p>--count=&lt;count&gt;</p><blockquote><p>By default the command shows all refs that match <strong>&lt;pattern&gt;</strong>. This option makes it stop after showing that many refs.</p></blockquote><p>--sort=&lt;key&gt;</p><blockquote><p>A field name to sort on. Prefix <strong>-</strong> to sort in descending order of the value. When unspecified, <strong>refname</strong> is used. You may use the --sort=&lt;key&gt; option multiple times, in which case the last key becomes the primary key.</p></blockquote><p>--format=&lt;format&gt;</p><blockquote><p>A string that interpolates <strong>%(fieldname)</strong> from a ref being shown and the object it points at. If <strong>fieldname</strong> is prefixed with an asterisk (**** *) and the ref points at a tag object, use the value for the field in the object which the tag object refers to (instead of the field in the tag object). When unspecified, <strong>&lt;format&gt;</strong> defaults to <strong>%(objectname) SPC %(objecttype) TAB %(refname)</strong>. It also interpolates <strong>%%</strong> to <strong>%</strong>, and <strong>%xx</strong> where <strong>xx</strong> are hex digits interpolates to character with hex code <strong>xx</strong>; for example <strong>%00</strong> interpolates to <strong>\\0</strong> (NUL), <strong>%09</strong> to <strong>\\t</strong> (TAB) and <strong>%0a</strong> to <strong>\\n</strong> (LF).</p></blockquote><p>--color[=&lt;when&gt;]</p><blockquote><p>Respect any colors specified in the <strong>--format</strong> option. The <strong>&lt;when&gt;</strong> field must be one of <strong>always</strong>, <strong>never</strong>, or <strong>auto</strong> (if <strong>&lt;when&gt;</strong> is absent, behave as if <strong>always</strong> was given).</p></blockquote><p>--shell, --perl, --python, --tcl</p><blockquote><p>If given, strings that substitute <strong>%(fieldname)</strong> placeholders are quoted as string literals suitable for the specified host language. This is meant to produce a scriptlet that can directly be \`eval\`ed.</p></blockquote><p>--points-at=&lt;object&gt;</p><blockquote><p>Only list refs which points at the given object.</p></blockquote><p>--merged[=&lt;object&gt;]</p><blockquote><p>Only list refs whose tips are reachable from the specified commit (HEAD if not specified).</p></blockquote><p>--no-merged[=&lt;object&gt;]</p><blockquote><p>Only list refs whose tips are not reachable from the specified commit (HEAD if not specified).</p></blockquote><p>--contains[=&lt;object&gt;]</p><blockquote><p>Only list refs which contain the specified commit (HEAD if not specified).</p></blockquote><p>--no-contains[=&lt;object&gt;]</p><blockquote><p>Only list refs which don&#39;t contain the specified commit (HEAD if not specified).</p></blockquote><p>--ignore-case</p><blockquote><p>Sorting and filtering refs are case insensitive.</p></blockquote><h2 id="field-names" tabindex="-1">FIELD NAMES <a class="header-anchor" href="#field-names" aria-label="Permalink to &quot;FIELD NAMES&quot;">​</a></h2><p>Various values from structured fields in referenced objects can be used to interpolate into the resulting output, or as sort keys.</p><p>For all objects, the following names can be used:</p><p>refname</p><blockquote><p>The name of the ref (the part after $GIT_DIR/). For a non-ambiguous short name of the ref append <strong>:short</strong>. The option core.warnAmbiguousRefs is used to select the strict abbreviation mode. If <strong>lstrip=&lt;N&gt;</strong> (<strong>rstrip=&lt;N&gt;</strong>) is appended, strips <strong>&lt;N&gt;</strong> slash-separated path components from the front (back) of the refname (e.g. <strong>%(refname:lstrip=2)</strong> turns <strong>refs/tags/foo</strong> into <strong>foo</strong> and <strong>%(refname:rstrip=2)</strong> turns <strong>refs/tags/foo</strong> into <strong>refs</strong>). If <strong>&lt;N&gt;</strong> is a negative number, strip as many path components as necessary from the specified end to leave <strong>-&lt;N&gt;</strong> path components (e.g. <strong>%(refname:lstrip=-2)</strong> turns <strong>refs/tags/foo</strong> into <strong>tags/foo</strong> and <strong>%(refname:rstrip=-1)</strong> turns <strong>refs/tags/foo</strong> into <strong>refs</strong>). When the ref does not have enough components, the result becomes an empty string if stripping with positive &lt;N&gt;, or it becomes the full refname if stripping with negative &lt;N&gt;. Neither is an error.</p><p><strong>strip</strong> can be used as a synonym to <strong>lstrip</strong>.</p></blockquote><p>objecttype</p><blockquote><p>The type of the object (<strong>blob</strong>, <strong>tree</strong>, <strong>commit</strong>, <strong>tag</strong>).</p></blockquote><p>objectsize</p><blockquote><p>The size of the object (the same as <em>git cat-file -s</em> reports). Append <strong>:disk</strong> to get the size, in bytes, that the object takes up on disk. See the note about on-disk sizes in the <strong>CAVEATS</strong> section below.</p></blockquote><p>objectname</p><blockquote><p>The object name (aka SHA-1). For a non-ambiguous abbreviation of the object name append <strong>:short</strong>. For an abbreviation of the object name with desired length append <strong>:short=&lt;length&gt;</strong>, where the minimum length is MINIMUM_ABBREV. The length may be exceeded to ensure unique object names.</p></blockquote><p>deltabase</p><blockquote><p>This expands to the object name of the delta base for the given object, if it is stored as a delta. Otherwise it expands to the null object name (all zeroes).</p></blockquote><p>upstream</p><blockquote><p>The name of a local ref which can be considered &quot;upstream&quot; from the displayed ref. Respects <strong>:short</strong>, <strong>:lstrip</strong> and <strong>:rstrip</strong> in the same way as <strong>refname</strong> above. Additionally respects <strong>:track</strong> to show &quot;[ahead N, behind M]&quot; and <strong>:trackshort</strong> to show the terse version: &quot;&gt;&quot; (ahead), &quot;&lt;&quot; (behind), &quot;&lt;&gt;&quot; (ahead and behind), or &quot;=&quot; (in sync). <strong>:track</strong> also prints &quot;[gone]&quot; whenever unknown upstream ref is encountered. Append <strong>:track,nobracket</strong> to show tracking information without brackets (i.e &quot;ahead N, behind M&quot;).</p><p>For any remote-tracking branch <strong>%(upstream)</strong>, <strong>%(upstream:remotename)</strong> and <strong>%(upstream:remoteref)</strong> refer to the name of the remote and the name of the tracked remote ref, respectively. In other words, the remote-tracking branch can be updated explicitly and individually by using the refspec <strong>%(upstream:remoteref):%(upstream)</strong> to fetch from <strong>%(upstream:remotename)</strong>.</p><p>Has no effect if the ref does not have tracking information associated with it. All the options apart from <strong>nobracket</strong> are mutually exclusive, but if used together the last option is selected.</p></blockquote><p>push</p><blockquote><p>The name of a local ref which represents the <strong>@{push}</strong> location for the displayed ref. Respects <strong>:short</strong>, <strong>:lstrip</strong>, <strong>:rstrip</strong>, <strong>:track</strong>, <strong>:trackshort</strong>, <strong>:remotename</strong>, and <strong>:remoteref</strong> options as <strong>upstream</strong> does. Produces an empty string if no <strong>@{push}</strong> ref is configured.</p></blockquote><p>HEAD</p><blockquote><p><em>*</em> if HEAD matches current ref (the checked out branch), &#39; &#39; otherwise.</p></blockquote><p>color</p><blockquote><p>Change output color. Followed by <strong>:&lt;colorname&gt;</strong>, where color names are described under Values in the &quot;CONFIGURATION FILE&quot; section of <strong>git-config</strong>(1). For example, <strong>%(color:bold red)</strong>.</p></blockquote><p>align</p><blockquote><p>Left-, middle-, or right-align the content between %(align:...) and %(end). The &quot;align:&quot; is followed by <strong>width=&lt;width&gt;</strong> and <strong>position=&lt;position&gt;</strong> in any order separated by a comma, where the <strong>&lt;position&gt;</strong> is either left, right or middle, default being left and <strong>&lt;width&gt;</strong> is the total length of the content with alignment. For brevity, the &quot;width=&quot; and/or &quot;position=&quot; prefixes may be omitted, and bare &lt;width&gt; and &lt;position&gt; used instead. For instance, <strong>%(align:&lt;width&gt;,&lt;position&gt;)</strong>. If the contents length is more than the width then no alignment is performed. If used with <strong>--quote</strong> everything in between %(align:...) and %(end) is quoted, but if nested then only the topmost level performs quoting.</p></blockquote><p>if</p><blockquote><p>Used as %(if)...%(then)...%(end) or %(if)...%(then)...%(else)...%(end). If there is an atom with value or string literal after the %(if) then everything after the %(then) is printed, else if the %(else) atom is used, then everything after %(else) is printed. We ignore space when evaluating the string before %(then), this is useful when we use the %(HEAD) atom which prints either &quot;*&quot; or &quot; &quot; and we want to apply the <em>if</em> condition only on the <em>HEAD</em> ref. Append &quot;:equals=&lt;string&gt;&quot; or &quot;:notequals=&lt;string&gt;&quot; to compare the value between the %(if:...) and %(then) atoms with the given string.</p></blockquote><p>symref</p><blockquote><p>The ref which the given symbolic ref refers to. If not a symbolic ref, nothing is printed. Respects the <strong>:short</strong>, <strong>:lstrip</strong> and <strong>:rstrip</strong> options in the same way as <strong>refname</strong> above.</p></blockquote><p>worktreepath</p><blockquote><p>The absolute path to the worktree in which the ref is checked out, if it is checked out in any linked worktree. Empty string otherwise.</p></blockquote><p>In addition to the above, for commit and tag objects, the header field names (<strong>tree</strong>, <strong>parent</strong>, <strong>object</strong>, <strong>type</strong>, and <strong>tag</strong>) can be used to specify the value in the header field. Fields <strong>tree</strong> and <strong>parent</strong> can also be used with modifier <strong>:short</strong> and <strong>:short=&lt;length&gt;</strong> just like <strong>objectname</strong>.</p><p>For commit and tag objects, the special <strong>creatordate</strong> and <strong>creator</strong> fields will correspond to the appropriate date or name-email-date tuple from the <strong>committer</strong> or <strong>tagger</strong> fields depending on the object type. These are intended for working on a mix of annotated and lightweight tags.</p><p>Fields that have name-email-date tuple as its value (<strong>author</strong>, <strong>committer</strong>, and <strong>tagger</strong>) can be suffixed with <strong>name</strong>, <strong>email</strong>, and <strong>date</strong> to extract the named component. For email fields (<strong>authoremail</strong>, <strong>committeremail</strong> and <strong>taggeremail</strong>), <strong>:trim</strong> can be appended to get the email without angle brackets, and <strong>:localpart</strong> to get the part before the <strong>@</strong> symbol out of the trimmed email.</p><p>The raw data in an object is <strong>raw</strong>.</p><p>raw:size</p><blockquote><p>The raw data size of the object.</p></blockquote><p>Note that <strong>--format=%(raw)</strong> can not be used with <strong>--python</strong>, <strong>--shell</strong>, <strong>--tcl</strong>, because such language may not support arbitrary binary data in their string variable type.</p><p>The message in a commit or a tag object is <strong>contents</strong>, from which <strong>contents:&lt;part&gt;</strong> can be used to extract various parts out of:</p><p>contents:size</p><blockquote><p>The size in bytes of the commit or tag message.</p></blockquote><p>contents:subject</p><blockquote><p>The first paragraph of the message, which typically is a single line, is taken as the &quot;subject&quot; of the commit or the tag message. Instead of <strong>contents:subject</strong>, field <strong>subject</strong> can also be used to obtain same results. <strong>:sanitize</strong> can be appended to <strong>subject</strong> for subject line suitable for filename.</p></blockquote><p>contents:body</p><blockquote><p>The remainder of the commit or the tag message that follows the &quot;subject&quot;.</p></blockquote><p>contents:signature</p><blockquote><p>The optional GPG signature of the tag.</p></blockquote><p>contents:lines=N</p><blockquote><p>The first <strong>N</strong> lines of the message.</p></blockquote><p>Additionally, the trailers as interpreted by <strong>git-interpret-trailers</strong>(1) are obtained as <strong>trailers[:options]</strong> (or by using the historical alias <strong>contents:trailers[:options]</strong>). For valid [:option] values see <strong>trailers</strong> section of <strong>git-log</strong>(1).</p><p>For sorting purposes, fields with numeric values sort in numeric order (<strong>objectsize</strong>, <strong>authordate</strong>, <strong>committerdate</strong>, <strong>creatordate</strong>, <strong>taggerdate</strong>). All other fields are used to sort in their byte-value order.</p><p>There is also an option to sort by versions, this can be done by using the fieldname <strong>version:refname</strong> or its alias <strong>v:refname</strong>.</p><p>In any case, a field name that refers to a field inapplicable to the object referred by the ref does not cause an error. It returns an empty string instead.</p><p>As a special case for the date-type fields, you may specify a format for the date by adding <strong>:</strong> followed by date format name (see the values the <strong>--date</strong> option to <strong>git-rev-list</strong>(1) takes).</p><p>Some atoms like %(align) and %(if) always require a matching %(end). We call them &quot;opening atoms&quot; and sometimes denote them as %($open).</p><p>When a scripting language specific quoting is in effect, everything between a top-level opening atom and its matching %(end) is evaluated according to the semantics of the opening atom and only its result from the top-level is quoted.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>An example directly producing formatted text. Show the most recent 3 tagged commits:</p><blockquote><pre><code>#!/bin/sh

git for-each-ref --count=3 --sort=&#39;-*authordate&#39;  &lt;br&gt; &gt;     --format=&#39;From: %(*authorname) %(*authoremail)
Subject: %(*subject)
Date: %(*authordate)
Ref: %(*refname)

%(*body)
&#39; &#39;refs/tags&#39;
</code></pre></blockquote><p>A simple example showing the use of shell eval on the output, demonstrating the use of --shell. List the prefixes of all heads:</p><blockquote><pre><code>#!/bin/sh

git for-each-ref --shell --format=&quot;ref=%(refname)&quot; refs/heads |  &lt;br&gt; &gt;     while read entry
do
        eval &quot;$entry&quot;
        echo \`dirname $ref\`
done
</code></pre></blockquote><p>A bit more elaborate report on tags, demonstrating that the format may be an entire script:</p><blockquote><pre><code>#!/bin/sh

fmt=&#39;
        r=%(refname)
        t=%(*objecttype)
        T=\${r#refs/tags/}

        o=%(*objectname)
        n=%(*authorname)
        e=%(*authoremail)
        s=%(*subject)
        d=%(*authordate)
        b=%(*body)

        kind=Tag
        if test &quot;z$t&quot; = z
        then
                # could be a lightweight tag
                t=%(objecttype)
                kind=&quot;Lightweight tag&quot;
                o=%(objectname)
                n=%(authorname)
                e=%(authoremail)
                s=%(subject)
                d=%(authordate)
                b=%(body)
        fi
        echo &quot;$kind $T points at a $t object $o&quot;
        if test &quot;z$t&quot; = zcommit
        then
                echo &quot;The commit was authored by $n $e
at $d, and titled

    $s

Its message reads as:
&quot;
                echo &quot;$b&quot; | sed -e &quot;s/^/    /&quot;
                echo
        fi
&#39;

eval=\`git for-each-ref --shell --format=&quot;$fmt&quot;  &lt;br&gt; &gt;             --sort=&#39;*objecttype&#39;  &lt;br&gt; &gt;             --sort=-taggerdate  &lt;br&gt; &gt;             refs/tags\`
eval &quot;$eval&quot;
</code></pre></blockquote><p>An example to show the usage of %(if)...%(then)...%(else)...%(end). This prefixes the current branch with a star.</p><blockquote><pre><code>git for-each-ref --format=&quot;%(if)%(HEAD)%(then)* %(else)  %(end)%(refname:short)&quot; refs/heads/
</code></pre></blockquote><p>An example to show the usage of %(if)...%(then)...%(end). This prints the authorname, if present.</p><blockquote><pre><code>git for-each-ref --format=&quot;%(refname)%(if)%(authorname)%(then) Authored by: %(authorname)%(end)&quot;
</code></pre></blockquote><h2 id="caveats" tabindex="-1">CAVEATS <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;CAVEATS&quot;">​</a></h2><p>Note that the sizes of objects on disk are reported accurately, but care should be taken in drawing conclusions about which refs or objects are responsible for disk usage. The size of a packed non-delta object may be much larger than the size of objects which delta against it, but the choice of which object is the base and which is the delta is arbitrary and is subject to change during a repack.</p><p>Note also that multiple copies of an object may be present in the object database; in this case, it is undefined which copy&#39;s size or delta base will be reported.</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>When combining multiple <strong>--contains</strong> and <strong>--no-contains</strong> filters, only references that contain at least one of the <strong>--contains</strong> commits and contain none of the <strong>--no-contains</strong> commits are shown.</p><p>When combining multiple <strong>--merged</strong> and <strong>--no-merged</strong> filters, only references that are reachable from at least one of the <strong>--merged</strong> commits and from none of the <strong>--no-merged</strong> commits are shown.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-show-ref</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,106))])}const b=o(h,[["render",l]]);export{f as __pageData,b as default};
